import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { 
    Box, 
    Typography, 
    IconButton, 
    Tooltip,
    alpha,
    useTheme,
    Divider,
    Stack,
    CircularProgress
} from '@mui/material';
import { 
    Visibility as ViewIcon, 
    Edit as EditIcon, 
    Delete as DeleteIcon,
    FitnessCenter as ExerciseIcon,
    List as ListIcon,
    HelpOutline as TipsIcon,
} from '@mui/icons-material';
import DataTable from '../../../components/DataTable';
import DisplayChip from '../../../components/DisplayChip';
import DetailsModal from '../../../components/DetailsModal';
import ConfirmationModal from '../../../components/ConfirmationModal';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-hot-toast';

import { useSelector } from 'react-redux';
import { mapExerciseExport } from "../../../utils/exportMappers";
import { extractExportList, performExport } from "../../../utils/exportHelpers";
import dayjs from 'dayjs';
import ImageView from '../../../components/ImageView';
import ImageWithFallback from '../../../components/ImageWithFallback';
import VideoView from '../../../components/VideoView';
import AudioView from '../../../components/AudioView';


const BASE_URL = process.env.REACT_APP_API_BASE_URL;

const DIFFICULTY_COLORS = {
    beginner: '#4CC66E',
    intermediate: '#FFCC00',
    advanced: '#FF5050',
};

const CATEGORY_COLORS = {
    legs: '#5AC8FA',
    chest: '#FF5050',
    back: '#BF5AF2',
    shoulders: '#FF9F0A',
    arms: '#4CC66E',
    core: '#FF375F',
    cardio: '#64D2FF',
    full_body: '#AF52DE',
    Strength: '#5AC8FA',
    HIIT: '#FF5050',
    Yoga: '#BF5AF2',
    Cardio: '#FF9F0A',
};

const hasFieldValue = (value) => {
    if (value === null || value === undefined || value === '') return false;
    if (Array.isArray(value)) return value.length > 0;
    return true;
};

const Exercises = () => {
    const theme = useTheme();
    const [exercises, setExercises] = useState([]);
    const [isLoading, setIsLoading] = useState(false);
    const [totalCount, setTotalCount] = useState(0);
    const [page, setPage] = useState(0);
    const [rowsPerPage, setRowsPerPage] = useState(5);
    const [orderBy, setOrderBy] = useState('created_at');
    const [order, setOrder] = useState('desc');
    const [searchTerm, setSearchTerm] = useState('');

    const [openViewModal, setOpenViewModal] = useState(false);
    const [openDeleteModal, setOpenDeleteModal] = useState(false);
    const [selectedExercise, setSelectedExercise] = useState(null);
    const [exerciseToDelete, setExerciseToDelete] = useState(null);
    const [isExporting, setIsExporting] = useState(false);

    const navigate = useNavigate();
    const token = useSelector((state) => state.auth.token);


    const fetchExercises = useCallback(async () => {
        if (!token) return;
        setIsLoading(true);
        try {
            const queryParams = new URLSearchParams({
                page: page + 1,
                limit: rowsPerPage,
                sort_by: orderBy,
                sort_order: order,
                q: searchTerm
            });

            const response = await fetch(`${BASE_URL}/workouts/exercises?${queryParams.toString()}`, {
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                }
            });

            const result = await response.json();
            if (response.ok && !result.error) {
                setExercises(result.data.exercises || []);
                setTotalCount(result.data.total || 0);
            } else {
                toast.error(result.message || 'Failed to fetch exercises');
            }
        } catch (error) {
            console.error('Fetch error:', error);
            toast.error('Error connecting to Server');
        } finally {
            setIsLoading(false);
        }
    }, [token, page, rowsPerPage, orderBy, order, searchTerm]);

    const handleExport = async (dates, format) => {
        if (!token) return;
        setIsExporting(true);
        const toastId = toast.loading(`Exporting exercises as ${format.toUpperCase()}...`);
        try {
            const queryParams = new URLSearchParams({
                sort_by: orderBy,
                sort_order: order,
                q: searchTerm,
                not_pagination: 'true',
                start_date: dates.startDate.format('YYYY-MM-DD'),
                end_date: dates.endDate.format('YYYY-MM-DD'),
            });

            const response = await fetch(`${BASE_URL}/workouts/exercises?${queryParams.toString()}`, {
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                }
            });

            const result = await response.json();
            if (!response.ok || result.error) {
                throw new Error(result.message || 'Failed to fetch exercises for export');
            }

            const items = extractExportList(result, 'exercises');
            const filename = `Exercises_Export_${dates.startDate.format('YYYYMMDD')}_to_${dates.endDate.format('YYYYMMDD')}`;

            await performExport({
                items,
                mapper: mapExerciseExport,
                format,
                filename,
                sheetName: 'Exercises',
                entityName: 'exercises',
                toastId,
            });
        } catch (error) {
            console.error('Export error:', error);
            toast.error(error.message || 'Connection error during export', { id: toastId });
        } finally {
            setIsExporting(false);
        }
    };

    useEffect(() => {
        fetchExercises();
    }, [fetchExercises]);

    const handleSortChange = (property) => {
        const isAsc = orderBy === property && order === 'asc';
        setOrder(isAsc ? 'desc' : 'asc');
        setOrderBy(property);
        setPage(0);
    };

    const handleViewDetails = (exercise) => {
        setSelectedExercise(exercise);
        setOpenViewModal(true);
    };

    const handleAddClick = () => {
        navigate('/exercises/add');
    };

    const handleEditClick = (exercise) => {
        navigate(`/exercises/edit/${exercise.id}`);
    };


    const handleDeleteClick = (exercise) => {
        setExerciseToDelete(exercise);
        setOpenDeleteModal(true);
    };

    const handleConfirmDelete = async () => {
        if (!exerciseToDelete || !token) return;
        setIsLoading(true);
        try {
            const response = await fetch(`${BASE_URL}/workouts/exercises/${exerciseToDelete.id}`, {
                method: 'DELETE',
                headers: {
                    'Authorization': `Bearer ${token}`
                }
            });

            const result = await response.json();
            if (response.ok && !result.error) {
                toast.success('Exercise Deleted Successfully!');
                // Refetch data after delete
                await fetchExercises();
            } else {
                toast.error(result.message || 'Failed to delete exercise');
            }
        } catch (error) {
            console.error('Delete error:', error);
            toast.error('Error connecting to Server');
        } finally {
            setIsLoading(false);
            setOpenDeleteModal(false);
            setExerciseToDelete(null);
        }
    };



    const columns = useMemo(() => [
        {
            id: 'title',
            label: 'Exercise Name',
            sortable: true,
            render: (row) => (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                    <Box sx={{ 
                        width: 44, 
                        height: 44, 
                        borderRadius: '12px', 
                        display: 'flex', 
                        alignItems: 'center', 
                        justifyContent: 'center',
                        bgcolor: alpha(theme.palette.primary.main, 0.1),
                        color: theme.palette.primary.main,
                        overflow: 'hidden',
                        border: '1px solid rgba(255,255,255,0.05)'
                    }}>
                        <ImageWithFallback 
                            src={row.thumbnail_url} 
                            alt={row.title}
                            fallbackIcon={ExerciseIcon}
                            sx={{ width: '100%', height: '100%', objectFit: 'cover' }}
                        />
                    </Box>
                    <Box>
                        <Typography sx={{ color: '#FFFFFF', fontWeight: 600, fontSize: '0.875rem' }}>
                            {row.title}
                        </Typography>
                    </Box>
                </Box>
            )
        },
        {
            id: 'category',
            label: 'Category',
            sortable: true,
            render: (row) => (
                <DisplayChip
                    label={row.category || 'N/A'}
                    size="small"
                    sx={{
                        bgcolor: alpha(CATEGORY_COLORS[row.category] || '#8B8D97', 0.15),
                        color: CATEGORY_COLORS[row.category] || '#8B8D97',
                        fontWeight: 600,
                        fontSize: '0.75rem',
                        textTransform: 'capitalize',
                        border: `1px solid ${alpha(CATEGORY_COLORS[row.category] || '#8B8D97', 0.3)}`,
                    }}
                />
            )
        },
        {
            id: 'target_muscle_group',
            label: 'Muscle Group',
            sortable: false,
            render: (row) => (
                hasFieldValue(row.target_muscle_group) ? (
                    <Typography
                        sx={{
                            color: '#FFFFFF',
                            fontSize: '0.875rem',
                            maxWidth: 160,
                            overflow: 'hidden',
                            textOverflow: 'ellipsis',
                            whiteSpace: 'nowrap',
                        }}
                        title={row.target_muscle_group}
                    >
                        {row.target_muscle_group}
                    </Typography>
                ) : (
                    <Typography sx={{ color: '#8B8D97', fontSize: '0.875rem' }}>-</Typography>
                )
            ),
        },
        {
            id: 'is_premium',
            label: 'Access',
            sortable: true,
            render: (row) => (
                <DisplayChip
                    label={row.is_premium ? 'Premium' : 'Free'}
                    size="small"
                    sx={{
                        bgcolor: alpha(row.is_premium ? '#FFCC00' : '#4CC66E', 0.15),
                        color: row.is_premium ? '#FFCC00' : '#4CC66E',
                        fontWeight: 600,
                        fontSize: '0.75rem',
                        border: `1px solid ${alpha(row.is_premium ? '#FFCC00' : '#4CC66E', 0.3)}`,
                    }}
                />
            ),
        },
        {
            id: 'created_at',
            label: 'Date Added',
            sortable: true,
            render: (row) => (
                <Typography sx={{ color: '#8B8D97', fontSize: '0.875rem' }}>
                    {row.created_at ? new Date(row.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : '-'}
                </Typography>
            )
        },
        {
            id: 'actions',
            label: 'Actions',
            render: (row) => (
                <Box sx={{ display: 'flex', gap: 1 }}>
                    <Tooltip title="View Details">
                        <IconButton 
                            size="small" 
                            onClick={() => handleViewDetails(row)}
                            sx={{ color: '#9F6EDA', bgcolor: alpha('#9F6EDA', 0.1), '&:hover': { bgcolor: alpha('#9F6EDA', 0.2) } }}
                        >
                            <ViewIcon fontSize="small" />
                        </IconButton>
                    </Tooltip>
                    <Tooltip title="Edit">
                        <IconButton 
                            size="small" 
                            onClick={() => handleEditClick(row)}
                            sx={{ color: '#9F6EDA', bgcolor: alpha('#9F6EDA', 0.1), '&:hover': { bgcolor: alpha('#9F6EDA', 0.2) } }}
                        >
                            <EditIcon fontSize="small" />
                        </IconButton>
                    </Tooltip>
                    <Tooltip title="Delete">
                        <IconButton 
                            size="small" 
                            onClick={() => handleDeleteClick(row)}
                            sx={{ color: '#FF5050', bgcolor: alpha('#FF5050', 0.1), '&:hover': { bgcolor: alpha('#FF5050', 0.2) } }}
                        >
                            <DeleteIcon fontSize="small" />
                        </IconButton>
                    </Tooltip>
                </Box>
            )
        }
    ], [theme]);

    const exerciseDetailsData = useMemo(() => {
        if (!selectedExercise) return [];
        const items = [];
        if (hasFieldValue(selectedExercise.title)) {
            items.push({ label: 'Exercise Title', value: selectedExercise.title });
        }
        if (hasFieldValue(selectedExercise.category)) {
            items.push({ label: 'Category', value: selectedExercise.category });
        }
        if (hasFieldValue(selectedExercise.difficulty)) {
            items.push({
                label: 'Difficulty Level',
                value: selectedExercise.difficulty,
                color: DIFFICULTY_COLORS[selectedExercise.difficulty],
            });
        }
        if (hasFieldValue(selectedExercise.target_muscle_group)) {
            items.push({ label: 'Muscle Group', value: selectedExercise.target_muscle_group, color: '#5AC8FA' });
        }
        if (hasFieldValue(selectedExercise.duration_seconds)) {
            items.push({ label: 'Duration', value: `${selectedExercise.duration_seconds} seconds` });
        }
        if (hasFieldValue(selectedExercise.default_rest_time_seconds)) {
            items.push({ label: 'Rest Time', value: `${selectedExercise.default_rest_time_seconds} seconds` });
        }
        if (selectedExercise.is_premium === true) {
            items.push({ label: 'Access', value: 'Premium', color: '#FFCC00' });
        }
        if (hasFieldValue(selectedExercise.created_at)) {
            items.push({
                label: 'Date Created',
                value: new Date(selectedExercise.created_at).toLocaleString('en-US', {
                    month: 'short',
                    day: 'numeric',
                    year: 'numeric',
                    hour: '2-digit',
                    minute: '2-digit',
                }),
            });
        }
        return items;
    }, [selectedExercise]);

    return (
        <Box sx={{ p: { xs: 1, md: 3 } }}>
            <DataTable
                title="Manage Exercises"
                columns={columns}
                data={exercises}
                isLoading={isLoading}
                onAddClick={handleAddClick}
                addLabel="Add Exercise"
                onExport={handleExport}
                isExporting={isExporting}
                searchTerm={searchTerm}
                onSearchChange={(val) => {
                    setSearchTerm(val);
                    setPage(0);
                }}
                orderBy={orderBy}
                order={order}
                onSortChange={handleSortChange}
                pagination={{
                    page: page,
                    rowsPerPage: rowsPerPage,
                    totalCount: totalCount,
                    onPageChange: (_, newPage) => setPage(newPage),
                    onRowsPerPageChange: (e) => {
                        setRowsPerPage(parseInt(e.target.value, 10));
                        setPage(0);
                    }
                }}
                onEditClick={handleEditClick}
                emptyTitle="No exercises found"
               
            />

            {selectedExercise && (
                <DetailsModal
                    open={openViewModal}
                    onClose={() => setOpenViewModal(false)}
                    title="Exercise Details"
                    data={exerciseDetailsData}
                    maxWidth="sm"
                >
                    <Box sx={{ mt: 3 }}>
                        {selectedExercise.thumbnail_url && (
                            <Box sx={{ mb: 3, borderRadius: '20px', overflow: 'hidden', border: '1px solid rgba(255,255,255,0.1)', bgcolor: '#000' }}>
                                <Typography variant="caption" sx={{ color: '#8B8D97', p: 1.5, pb: 0, display: 'block', fontWeight: 600, textTransform: 'uppercase' }}>
                                    Thumbnail
                                </Typography>
                                <ImageView
                                    src={selectedExercise.thumbnail_url}
                                    alt={selectedExercise.title}
                                    sx={{ width: '100%', maxHeight: '320px', objectFit: 'contain', display: 'block' }}
                                />
                            </Box>
                        )}

                        {(selectedExercise.video_url || selectedExercise.audio_url) && (
                            <Box sx={{ mb: 4, borderRadius: '20px', overflow: 'hidden', border: '1px solid rgba(255,255,255,0.1)' }}>
                                {selectedExercise.video_url && (
                                    <Box sx={{ borderRadius: 2, overflow: 'hidden', border: '1px solid #474747' }}>
                                        <Typography variant="caption" sx={{ color: '#8B8D97', p: 1.5, pb: 0, display: 'block', fontWeight: 600, textTransform: 'uppercase' }}>
                                            Video
                                        </Typography>
                                        <VideoView
                                            src={selectedExercise.video_url}
                                            sx={{ width: '100%', display: 'block' }}
                                        />
                                    </Box>
                                )}

                                {selectedExercise.audio_url && (
                                    <Box sx={{ p: 2 }}>
                                        <Typography variant="caption" sx={{ color: '#8B8D97', mb: 1, display: 'block', fontWeight: 600, textTransform: 'uppercase' }}>
                                            Audio Guide
                                        </Typography>
                                        <AudioView
                                            src={selectedExercise.audio_url}
                                            sx={{ width: '100%' }}
                                        />
                                    </Box>
                                )}
                            </Box>
                        )}

                        {(selectedExercise.instructions?.steps?.length > 0 ||
                            selectedExercise.instructions?.dos?.length > 0) && (
                        <>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2.5 }}>
                            <ListIcon sx={{ color: theme.palette.primary.main }} />
                            <Typography variant="h6" sx={{ color: '#FFFFFF', fontWeight: 700, fontSize: '1.1rem' }}>
                                Instructional Guide
                            </Typography>
                        </Box>

                        <Stack spacing={4}>
                            {/* Execution Steps */}
                            {selectedExercise.instructions?.steps?.length > 0 && (
                                <Box sx={{ 
                                    p: 3, 
                                    borderRadius: '20px', 
                                    bgcolor: 'rgba(255, 255, 255, 0.02)',
                                    border: '1px solid rgba(255, 255, 255, 0.06)'
                                }}>
                                    <Typography variant="subtitle2" sx={{ color: theme.palette.primary.main, fontWeight: 800, mb: 2, textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                                        How to Execute
                                    </Typography>
                                    <Stack spacing={1.5}>
                                        {selectedExercise.instructions.steps.map((step, idx) => (
                                            <Box key={idx} sx={{ display: 'flex', gap: 2 }}>
                                                <Typography sx={{ color: theme.palette.primary.main, fontWeight: 900, fontSize: '0.9rem' }}>{idx + 1}.</Typography>
                                                <Typography variant="body2" sx={{ color: '#FFFFFF', fontSize: '0.9rem', lineHeight: 1.6 }}>{step}</Typography>
                                            </Box>
                                        ))}
                                    </Stack>
                                </Box>
                            )}

                            {selectedExercise.instructions?.dos?.length > 0 && (
                                <Box sx={{ 
                                    p: 3, 
                                    borderRadius: '20px', 
                                    bgcolor: alpha('#4CC66E', 0.03),
                                    border: `1px solid ${alpha('#4CC66E', 0.1)}`
                                }}>
                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2 }}>
                                        <TipsIcon sx={{ color: '#4CC66E', fontSize: 18 }} />
                                        <Typography variant="subtitle2" sx={{ color: '#4CC66E', fontWeight: 800, textTransform: 'uppercase' }}>
                                            Things To Do (Dos)
                                        </Typography>
                                    </Box>
                                    <Stack spacing={1}>
                                        {selectedExercise.instructions.dos.map((tip, idx) => (
                                            <Box key={idx} sx={{ display: 'flex', gap: 1 }}>
                                                <Box sx={{ mt: 1, minWidth: 6, width: 6, height: 2, bgcolor: '#4CC66E', borderRadius: 2 }} />
                                                <Typography variant="body2" sx={{ color: '#8B8D97', fontSize: '0.85rem' }}>{tip}</Typography>
                                            </Box>
                                        ))}
                                    </Stack>
                                </Box>
                            )}
                        </Stack>
                        </>
                        )}
                    </Box>
                </DetailsModal>
            )}



            <ConfirmationModal
                open={openDeleteModal}
                onClose={() => setOpenDeleteModal(false)}
                onConfirm={handleConfirmDelete}
                title="Delete Exercise?"
                message={`Are you sure you want to delete "${exerciseToDelete?.title}"? This action cannot be undone.`}
                confirmText="Delete"
                confirmColor="error"
                loading={isLoading}
            />
        </Box>
    );
};

export default Exercises;
